import sys
import time
import math
from collections import deque

def evaluate_expression(expr):
    try:
        return eval(expr)
    except ZeroDivisionError:
        return float('inf')  # Should not happen per problem statement
    except:
        return None

def process_file(path, rate_limit):
    try:
        with open(path, 'r') as file:
            lines = [line.strip() for line in file if line.strip()]
            for line in lines:
                if not line:
                    continue
                result = evaluate_expression(line)
                if result is not None:
                    if rate_limit == 0 or not rate_limited:
                        print(f"{line} = {result:.2f}" if isinstance(result, float) and not result.is_integer() else f"{line} = {int(result)}")
                        rate_limited = False
                    else:
                        rate_limited = True
                        time.sleep(1)
    except IOError:
        sys.stderr.write("ERROR: cannot read file\n")
        sys.exit(1)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python script.py <N>\n")
        sys.exit(1)

    try:
        N = int(sys.argv[1])
    except ValueError:
        sys.stderr.write("ERROR: N must be an integer\n")
        sys.exit(1)

    if N < 0 or N > 1000:
        sys.stderr.write("ERROR: N must be between 0 and 1000\n")
        sys.exit(1)

    path = sys.stdin.readline().strip()
    rate_limited = False
    start_time = time.time()

    while True:
        current_time = time.time()
        if current_time - start_time >= 1 and N > 0:
            rate_limited = True
        process_file(path, N)
        if N == 0:
            break

if __name__ == "__main__":
    main()

import sys
import time
import math

def evaluate_expression(expr):
    try:
        # Replace spaces with empty string to handle multi-digit numbers and operators
        expr = expr.replace(" ", "")
        # Evaluate the expression safely
        result = eval(expr)
        return result
    except ZeroDivisionError:
        return float('inf')  # Should not occur per problem constraints
    except:
        return None

def main():
    if len(sys.argv) != 2:
        print("ERROR: cannot read file to stderr", file=sys.stderr)
        sys.exit(1)

    N = int(sys.argv[1])
    if N < 0 or N > 1000:
        print("ERROR: invalid N value", file=sys.stderr)
        sys.exit(1)

    file_path = sys.stdin.readline().strip()
    try:
        with open(file_path, 'r') as file:
            lines = [line.strip() for line in file if line.strip()]
    except IOError:
        print("ERROR: cannot read file to stderr", file=sys.stderr)
        sys.exit(1)

    last_print_time = 0
    for i, line in enumerate(lines, 1):
        try:
            expr = line
            result = evaluate_expression(expr)
            if result is None:
                print(f"{line} = ERROR", file=sys.stderr)
                continue

            if result == int(result):
                print(f"{line} = {int(result)}")
            else:
                print(f"{line} = {result:.2f}")

            if N > 0 and i % N == 0:
                time.sleep(1)
        except Exception as e:
            print(f"{line} = ERROR", file=sys.stderr)

if __name__ == "__main__":
    main()
